const SYSTEM = "Jesteś analitykiem finansowym małej firmy. Na podstawie danych (JSON) napisz zwięzłe podsumowanie miesiąca po polsku. Używaj tylko liczb z danych.\n\nOdpowiedz WYŁĄCZNIE poprawnym obiektem JSON z polami: {\"podsumowanie\": 3-5 zdań, \"najwazniejsze\": tablica maks. 5 punktów z liczbami, \"ryzyka\": tablica maks. 3 punktów}. Nie wymyślaj faktów, cen ani danych, których nie ma w treści.";
const user = `Dane za poprzedni miesiąc:\n${JSON.stringify($json).slice(0, 8000)}`;
return {
  json: {
    ...$json,
    _aiPrompt: String(user).slice(0, 12000),
  },
};

// Łączymy dane wejściowe (sprzed wywołania AI) z odpowiedzią modelu.
const ctx = { ...{} };
delete ctx._aiPrompt;
let out = {};
let aiError = '';
try {
  const raw = $json.output ?? '';
  out = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!out || typeof out !== 'object' || Array.isArray(out)) throw new Error('to nie obiekt');
} catch (e) {
  aiError = 'Nie udało się odczytać odpowiedzi AI: ' + e.message;
  out = {};
}
const defaults = {"podsumowanie":"","najwazniejsze":"","ryzyka":""};
for (const [k, v] of Object.entries(defaults)) if (out[k] === undefined || out[k] === null) out[k] = v;
for (const [k, v] of Object.entries(out)) if (typeof v === 'string') out[k] = v.slice(0, 4000);

return { json: { ...ctx, ...out, _aiOk: !aiError, _aiError: aiError } };
